describe('Loading States Accessibility', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should announce loading state to assistive technology when loading starts', () => {
        cy.get('#load-button').click(); // Replace with the actual selector for the loading trigger
        cy.get('#loading-indicator', { timeout: 10000 }).should('be.visible'); // Wait for loading indicator

        cy.get('#loading-indicator').should('have.attr', 'aria-live', 'assertive'); // Check aria-live attribute
        cy.get('#loading-indicator').should('contain', 'Loading...'); // Check loading message
    });

    it('should remove loading state announcement when loading completes', () => {
        cy.get('#load-button').click(); // Replace with the actual selector for the loading trigger
        cy.get('#loading-indicator', { timeout: 10000 }).should('be.visible'); // Wait for loading indicator

        cy.get('#loading-indicator').should('contain', 'Loading...'); // Check loading message

        // Simulate loading completion
        cy.intercept('GET', '/api/data', { fixture: 'data.json' }).as('getData'); // Replace with actual API call
        cy.wait('@getData');

        cy.get('#loading-indicator').should('not.exist'); // Ensure loading indicator is removed
        cy.get('#content').should('be.visible'); // Check that the content is visible after loading
    });
});
